/* TopoSurvey Mobile — interactive PWA prototype.
   User-controlled geolocation and local-only data. Never fabricates real GPS measurements. */
(() => {
'use strict';
const STORAGE_KEY='toposurvey_mobile_v1';
const MAX_FIX_AGE_MS=30000;
const PAGE_META={dashboard:['Beranda','OVERVIEW','grid'],capture:['Ambil Koordinat','GPS CAPTURE','crosshair'],map:['Peta Survei','MAP EXPLORER','map'],data:['Data Survei','DATA MANAGER','database'],history:['Riwayat','ACTIVITY LOG','clock'],export:['Ekspor Data','DATA EXPORT','download'],settings:['Pengaturan','PREFERENCES','settings']};
const ICONS={
 grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',
 crosshair:'<circle cx="12" cy="12" r="8"/><circle cx="12" cy="12" r="3"/><path d="M12 2v3m0 14v3M2 12h3m14 0h3"/>',
 map:'<path d="m3 6 6-3 6 3 6-3v15l-6 3-6-3-6 3V6Zm6-3v15m6-12v15"/>',
 database:'<ellipse cx="12" cy="5" rx="9" ry="3"/><path d="M3 5v14c0 4 18 4 18 0V5M3 12c0 4 18 4 18 0"/>',
 clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l4 2"/>',
 download:'<path d="M12 3v12m-4-4 4 4 4-4M4 17v4h16v-4"/>',
 settings:'<circle cx="12" cy="12" r="3"/><path d="M10 2h4l1 3 3 1 3-1 2 4-2 2v3l2 2-2 4-3-1-3 1-1 3h-4l-1-3-3-1-3 1-2-4 2-2v-3L1 9l2-4 3 1 3-1z" transform="translate(0,0) scale(.94) translate(.72,.72)"/>',
 plus:'<path d="M12 5v14M5 12h14"/>',
 arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',
 chevron:'<path d="m9 18 6-6-6-6"/>',
 arrowleft:'<path d="M19 12H5m6 6-6-6 6-6"/>',
 locate:'<path d="m3 11 18-8-8 18-2-8-8-2Z"/>',
 pin:'<path d="M20 10c0 5-8 12-8 12S4 15 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.4"/>',
 point:'<circle cx="12" cy="12" r="8"/><circle cx="12" cy="12" r="2"/>',
 gps:'<path d="M2 12a10 10 0 0 1 20 0M5 12a7 7 0 0 1 14 0M8 12a4 4 0 0 1 8 0M12 12v8"/>',
 layers:'<path d="m12 3 9 5-9 5-9-5 9-5Zm-9 9 9 5 9-5M3 16l9 5 9-5"/>',
 ruler:'<path d="M3 17 17 3l4 4L7 21l-4-4ZM8 12l3 3m1-7 3 3m1-7 3 3"/>',
 mountain:'<path d="m2 20 7-13 4 7 3-5 6 11H2Z"/>',
 check:'<path d="m4 12 5 5L20 6"/>',
 x:'<path d="M5 5l14 14M19 5 5 19"/>',
 search:'<circle cx="11" cy="11" r="7"/><path d="m16 16 5 5"/>',
 edit:'<path d="m3 17 0 4 4 0 12-12-4-4L3 17Zm11-11 4 4m-1-6 2-2 4 4-2 2"/>',
 trash:'<path d="M4 6h16M10 6V4h4v2m-8 0 1 15h10l1-15M10 10v7m4-7v7"/>',
 info:'<circle cx="12" cy="12" r="10"/><path d="M12 11v6m0-10h.01"/>',
 warning:'<path d="m12 2 10 18H2L12 2Zm0 7v5m0 3h.01"/>',
 refresh:'<path d="M20 7v5h-5M4 17v-5h5"/><path d="M5 9a8 8 0 0 1 14-2l1 5M4 12l1 5a8 8 0 0 0 14-2"/>',
 file:'<path d="M5 2h9l5 5v15H5V2Zm9 0v6h5M8 13h8m-8 4h8"/>',
 upload:'<path d="M12 16V3m-4 4 4-4 4 4M3 17v4h18v-4"/>',
 csv:'<rect x="3" y="3" width="18" height="18" rx="2"/><path d="M3 9h18M9 3v18M3 15h18M15 9v12"/>',
 geo:'<path d="m12 2 9 5-9 5-9-5 9-5Zm-9 5v10l9 5 9-5V7M12 12v10"/>',
 calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 2v6m10-6v6M3 11h18"/>',
 menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',
 home:'<path d="m3 10 9-8 9 8v11h-7v-7h-4v7H3V10Z"/>',
 wifi:'<path d="M2 9a15 15 0 0 1 20 0M5 13a10 10 0 0 1 14 0M9 17a5 5 0 0 1 6 0M12 21h.01"/>',
 clipboard:'<rect x="5" y="4" width="14" height="18" rx="2"/><path d="M9 4V2h6v2M9 11h6m-6 4h6"/>',
 archive:'<rect x="3" y="3" width="18" height="5" rx="1"/><path d="M5 8v13h14V8m-10 5h6"/>',
 filter:'<path d="M3 4h18l-7 8v7l-4 2v-9L3 4Z"/>',
 eye:'<path d="M2 12c5-8 15-8 20 0-5 8-15 8-20 0Z"/><circle cx="12" cy="12" r="3"/>',
 lock:'<rect x="5" y="11" width="14" height="11" rx="2"/><path d="M8 11V7a4 4 0 0 1 8 0v4"/>',
 sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l2 2m10 10 2 2M19 5l-2 2M7 17l-2 2"/>',
 pluscircle:'<circle cx="12" cy="12" r="9"/><path d="M12 7v10m-5-5h10"/>',
 compass:'<circle cx="12" cy="12" r="10"/><path d="m16 8-2 6-6 2 2-6 6-2Z"/>',
 globe:'<circle cx="12" cy="12" r="10"/><path d="M2 12h20M12 2c-6 5-6 15 0 20m0-20c6 5 6 15 0 20"/>',
 signal:'<path d="M3 19h2v2H3zm5-4h2v6H8zm5-5h2v11h-2zm5-7h2v18h-2z"/>',
 folder:'<path d="M2 6h8l2 2h10v12H2V6Z"/>',
 share:'<circle cx="18" cy="5" r="3"/><circle cx="5" cy="12" r="3"/><circle cx="18" cy="19" r="3"/><path d="m8 11 7-5m-7 8 7 4"/>',
 target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',
 copy:'<rect x="8" y="8" width="12" height="13" rx="2"/><path d="M16 8V4H4v13h4"/>',
 print:'<path d="M6 9V3h12v6M6 18H3V9h18v9h-3m-12-5h12v8H6v-8Z"/>',
 dots:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>'
};
function icon(name,cl=''){return `<svg class="${cl}" viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${ICONS[name]||ICONS.point}</svg>`;}
function esc(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function id(){return typeof crypto!=='undefined'&&crypto.randomUUID?crypto.randomUUID():`${Date.now()}-${Math.random().toString(16).slice(2)}`;}
function safeText(t,max=140){return String(t??'').trim().slice(0,max);}
function fmtDate(ts,opts={dateStyle:'medium',timeStyle:'short'}){return Number.isFinite(Number(ts))?new Intl.DateTimeFormat('id-ID',{timeZone:undefined,...opts}).format(new Date(Number(ts))):'—';}
function fmtNum(n,d=2){return Number.isFinite(Number(n))&&n!==null?new Intl.NumberFormat('id-ID',{minimumFractionDigits:d,maximumFractionDigits:d}).format(Number(n)):'—';}
function coord(n){return typeof n==='number'&&Number.isFinite(n)?n.toFixed(7):'—';}
function displayLength(n,d=1){if(n===null||n===undefined||!Number.isFinite(Number(n)))return '—';return db.settings.units==='ft'?`${fmtNum(Number(n)*3.280839895,d)} ft`:`${fmtNum(n,d)} m`;}
function formatElev(n){return n===null||n===undefined||!Number.isFinite(Number(n))?'Tidak tersedia':displayLength(n,1);}
function newState(){const p={id:id(),name:'Survei Lapangan',description:'Proyek pertama',createdAt:Date.now()};return {version:1,projects:[p],activeProjectId:p.id,points:[],history:[],settings:{accuracyThreshold:10,units:'m',theme:'dark',basemap:'osm'}};}
function loadState(){try{const raw=localStorage.getItem(STORAGE_KEY);if(!raw)return newState();const s=JSON.parse(raw);if(!Array.isArray(s.projects)||!Array.isArray(s.points)||!Array.isArray(s.history)||!s.projects.length)throw Error('Invalid saved schema');return {...newState(),...s,settings:{...newState().settings,...s.settings}};}catch(e){console.warn('Stored data could not be loaded',e);return newState();}}
let db=loadState();
let ui={page:'dashboard',pointQuery:'',dataProjectId:'all',historyProjectId:'all',exportProjectId:'active',dateFrom:'',dateTo:'',format:'csv',fix:null,gpsSearching:false,gpsError:'',lowQualityConsent:false,selectedPointId:null,mapCenter:{lat:-6.914744,lon:107.609810},mapZoom:15,mapProjectId:'active',mapBoundsInitialized:false};
let toastTimer=null;
function persist(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(db));return true;}catch(e){notify('Penyimpanan browser penuh atau tidak tersedia. Data belum tersimpan.',true);console.error(e);return false;}}
function logEvent(action,message,pointId=null,projectId=null){db.history.unshift({id:id(),action,message,pointId,projectId:projectId||db.activeProjectId,at:Date.now()});db.history=db.history.slice(0,600);}
function currentProject(){return db.projects.find(x=>x.id===db.activeProjectId)||db.projects[0];}
function projectName(pid){return db.projects.find(x=>x.id===pid)?.name||'Proyek dihapus';}
function selectedPoints(pid='active'){return db.points.filter(p=>pid==='all'||p.projectId===(pid==='active'?db.activeProjectId:pid));}
function pointList(){return selectedPoints(ui.dataProjectId).filter(p=>`${p.code} ${p.name} ${p.notes||''} ${projectName(p.projectId)}`.toLowerCase().includes(ui.pointQuery.trim().toLowerCase())).sort((a,b)=>b.recordedAt-a.recordedAt);}
function recentPoints(pid='active',limit=5){return selectedPoints(pid).sort((a,b)=>b.recordedAt-a.recordedAt).slice(0,limit);}
function nextPointCode(){const codeNums=selectedPoints('active').map(p=>Number((p.code||'').match(/^TP-(\d+)$/)?.[1]||0));return `TP-${String(Math.max(0,...codeNums)+1).padStart(3,'0')}`;}
function qualityBadge(p){return p.source==='DEMO'?'<span class="pill orange">DATA DEMO</span>':p.quality==='LOW_QUALITY'?'<span class="pill orange">AKURASI RENDAH</span>':'<span class="pill green">TERCATAT</span>';}
function notify(message,error=false){const node=document.querySelector('#toast');node.textContent=message;node.classList.toggle('error',!!error);node.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>node.classList.remove('show'),3600);}
function mutate(callback){const previous=JSON.stringify(db);callback();if(!persist()){db=JSON.parse(previous);return false;}render();return true;}
function pageTitle(title,subtitle,action=''){return `<div class="section-top"><div><span class="eyebrow">${esc(subtitle)}</span><h1 class="hero-title">${esc(title)}</h1></div>${action?`<div class="page-actions">${action}</div>`:''}</div>`;}
function badgeOnline(){return navigator.onLine?'<span class="pill green">ONLINE</span>':'<span class="pill orange">OFFLINE</span>';}
function btn(action,label,ico=null,klass='',extra=''){return `<button type="button" class="btn ${klass}" data-action="${esc(action)}" ${extra}>${ico?icon(ico):''}${esc(label)}</button>`;}
function empty(ico,title,desc,buttons=''){return `<div class="empty-state"><div class="empty-icon">${icon(ico)}</div><h3>${esc(title)}</h3><p>${esc(desc)}</p>${buttons}</div>`;}
function projectSelect(selected,attributes='',includeAll=false){let opts=(includeAll?'<option value="all"'+(selected==='all'?' selected':'')+'>Semua proyek</option>':'')+db.projects.map(p=>`<option value="${esc(p.id)}" ${selected===p.id?'selected':''}>${esc(p.name)}</option>`).join('');return `<select class="select" ${attributes}>${opts}</select>`;}
function renderNav(){const make=(key,mobile=false)=>`<button class="${mobile?'mobile-nav-item':'nav-link'} ${ui.page===key?'active':''}" data-action="navigate" data-page="${key}" aria-current="${ui.page===key?'page':'false'}">${icon(PAGE_META[key][2])}<span>${mobile?(key==='capture'?'Ambil Titik':key==='data'?'Data':key==='dashboard'?'Beranda':key==='settings'?'Lainnya':PAGE_META[key][0]):PAGE_META[key][0]}</span>${!mobile?'<span class="nav-number">0'+(Object.keys(PAGE_META).indexOf(key)+1)+'</span>':''}</button>`;
document.querySelector('#desktopNav').innerHTML=Object.keys(PAGE_META).map(key=>make(key)).join('');
document.querySelector('#mobileNav').innerHTML=['dashboard','map','capture','data','settings'].map(key=>make(key,true)).join('');}
function render(){document.body.dataset.theme=db.settings.theme;document.querySelector('#pageCrumb').textContent=PAGE_META[ui.page][1];renderNav();document.querySelector('#screen').innerHTML=({dashboard:renderDashboard,capture:renderCapture,map:renderMap,data:renderData,history:renderHistory,export:renderExport,settings:renderSettings}[ui.page])();renderNetwork();if(ui.page==='map')requestAnimationFrame(initMap);}
function renderNetwork(){const n=document.querySelector('#networkPill');n.textContent=navigator.onLine?'ONLINE · LOCAL STORAGE':'OFFLINE · LOCAL STORAGE';document.querySelector('#connectionSidebar').innerHTML=`<span class="online-led ${navigator.onLine?'':'offline'}"></span> ${navigator.onLine?'Terhubung ke internet':'Mode offline: data lokal'}`;}
function dashboardStat(label,value,note,ico){return `<div class="panel stat-card"><div class="stat-top"><span class="stat-title">${esc(label)}</span><span class="stat-icon">${icon(ico)}</span></div><div class="stat-value">${esc(value)}</div><div class="stat-note">${esc(note)}</div></div>`;}
function renderDashboard(){const pts=selectedPoints();const nElev=pts.filter(p=>p.altitude!==null).length;const last=pts.length?pts.sort((a,b)=>b.recordedAt-a.recordedAt)[0]:null;const actions=[['capture','Ambil Titik','crosshair','Baca koordinat'],['map','Peta Survei','map','Lihat titik peta'],['data','Data Survei','database','Kelola titik'],['history','Riwayat','clock','Jejak aktivitas'],['export','Ekspor','download','Unduh data'],['settings','Pengaturan','settings','Setel aplikasi']];return `${pageTitle('Pusat Kendali Survei','DASHBOARD / RINGKASAN',`${btn('new-project','Proyek Baru','plus','btn-outline')}`)}
<div class="section-top" style="margin-top:-7px"><div><p class="intro" style="margin:0">Kelola titik pengukuran lapangan dengan GPS perangkat, lalu simpan dan ekspor hasilnya secara lokal.</p></div><div class="project-switch">${projectSelect(db.activeProjectId,'data-change="project"')}</div></div>
<div class="stat-grid">${dashboardStat('Titik Tersimpan',pts.length,'Dalam proyek aktif','point')}${dashboardStat('Total Proyek',db.projects.length,'Disimpan di perangkat','folder')}${dashboardStat('Titik Berelevasi',nElev,`${pts.length-nElev} tanpa elevasi`,'mountain')}${dashboardStat('Aktivitas Terakhir',last?fmtDate(last.recordedAt,{day:'numeric',month:'short'}):'—',last?'Tanggal titik terbaru':'Belum ada titik','calendar')}</div>
<div class="dashboard-grid"><div class="dashboard-column"><div class="panel spotlight"><span class="eyebrow">READY TO SURVEY</span><h2>Ukur titik lapangan,<br/>langsung dari genggaman.</h2><p>Rekam koordinat latitude, longitude, elevasi GPS, dan metadata kualitas. Semua data tersimpan di perangkat.</p>${btn('navigate','Mulai Pengukuran','crosshair','btn-primary','data-page="capture"')}<div class="spotlight-icon">${icon('compass')}</div></div><div class="panel panel-pad"><div class="panel-head"><div><h2 class="panel-title">Menu Cepat</h2><div class="panel-subtitle">Fungsi utama untuk kebutuhan survei</div></div></div><div class="quick-grid">${actions.map(a=>`<button class="quick-card" data-action="navigate" data-page="${a[0]}">${icon(a[2])}<strong>${a[1]}</strong><span>${a[3]}</span></button>`).join('')}</div></div></div><div class="dashboard-column"><div class="panel panel-pad"><div class="panel-head"><div><h2 class="panel-title">Proyek Aktif</h2><p class="panel-subtitle">Data disimpan secara offline</p></div>${badgeOnline()}</div><div style="display:flex;align-items:center;gap:12px"><div class="point-icon" style="width:47px;height:47px">${icon('folder')}</div><div><strong style="font-size:14px">${esc(currentProject().name)}</strong><div class="caption">Dibuat ${fmtDate(currentProject().createdAt,{day:'numeric',month:'short',year:'numeric'})}</div></div></div><p class="caption" style="margin:15px 0">${esc(currentProject().description||'Tanpa deskripsi proyek.')}</p>${btn('manage-projects','Kelola Semua Proyek','folder','btn-outline btn-sm')}</div><div class="panel panel-pad"><div class="panel-head"><div><h2 class="panel-title">Titik Terbaru</h2><p class="panel-subtitle">Hasil pengukuran yang baru disimpan</p></div><button class="text-action" data-action="navigate" data-page="data">Lihat Semua ${icon('chevron')}</button></div>${last?`<div class="recent-list">${recentPoints('active',5).map(p=>`<div class="recent-item"><div class="point-icon">${icon('pin')}</div><div class="recent-main"><strong>${esc(p.code)} · ${esc(p.name)}</strong><small>${coord(p.latitude)}, ${coord(p.longitude)}</small></div><div class="recent-right"><strong>${esc(formatElev(p.altitude))}</strong><small>${fmtDate(p.recordedAt,{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})}</small></div></div>`).join('')}</div>`:empty('point','Belum ada titik','Ambil koordinat GPS atau aktifkan data demonstrasi melalui menu Pengaturan.')} </div></div></div>
<p class="footer-note">TopoSurvey Prototype v1.0 · Prototipe PWA, bukan APK native. Ketelitian GPS ponsel tidak setara dengan instrumen survei geodesi.</p>`;}
function fixStatus(){if(ui.gpsSearching)return ['MENCARI LOKASI','Menunggu posisi perangkat dengan akurasi terbaik','orange'];if(ui.gpsError)return ['GPS BELUM SIAP',ui.gpsError,'red'];if(!ui.fix)return ['BELUM ADA FIX','Tekan “Ambil Lokasi GPS” untuk mulai','neutral'];if(ui.fix.source==='DEMO')return ['MODE DEMONSTRASI','Nilai simulasi — bukan data GPS asli','orange'];const age=Date.now()-ui.fix.fixTime;return age>MAX_FIX_AGE_MS?['FIX KEDALUWARSA','Lokasi lebih dari 30 detik; ambil ulang','orange']:['FIX BERHASIL',`Diperoleh ${fmtDate(ui.fix.fixTime)}`,'green'];}
function hasValidFix(){const f=ui.fix;if(!f||!Number.isFinite(f.latitude)||!Number.isFinite(f.longitude)||f.latitude < -90||f.latitude >90||f.longitude < -180||f.longitude>180)return false;return f.source==='DEMO'||Date.now()-f.fixTime>=0&&Date.now()-f.fixTime<=MAX_FIX_AGE_MS;}
function qualityLow(){return !!ui.fix&&ui.fix.source!=='DEMO'&&(!Number.isFinite(ui.fix.hAccuracy)||ui.fix.hAccuracy>Number(db.settings.accuracyThreshold));}
function renderCapture(){const f=ui.fix,stat=fixStatus(),has=hasValidFix(),isLow=qualityLow(),isDemo=f?.source==='DEMO';const number=(v)=>Number.isFinite(v)?displayLength(v,1):'—';return `${pageTitle('Ambil Koordinat','FIELD MEASUREMENT',`${btn('navigate','Lihat Data','database','btn-outline','data-page="data"')}`)}<div class="gps-layout"><div class="panel gps-panel"><div class="panel-head"><div><h2 class="panel-title">Posisi Perangkat</h2><p class="panel-subtitle">Fix lokasi baru dari browser / layanan lokasi Android</p></div><span class="pill ${stat[2]}">${esc(stat[0])}</span></div><div class="gps-banner"><div class="gps-ring">${icon('gps')}</div><div class="gps-info"><strong>${esc(stat[0])}</strong><span>${esc(stat[1])}</span></div><span class="gps-flag">${f?f.source==='DEMO'?'SIMULASI':'PERANGKAT':'GPS'}</span></div><div class="gps-big-coords"><div class="metric"><div class="metric-label">LATITUDE / °</div><div class="metric-value">${f?coord(f.latitude):'—'}</div><div class="metric-small">Lintang geografis</div></div><div class="metric"><div class="metric-label">LONGITUDE / °</div><div class="metric-value">${f?coord(f.longitude):'—'}</div><div class="metric-small">Bujur geografis</div></div></div><div class="gps-support"><div class="metric"><div class="metric-label">ELEVASI (WGS84)</div><div class="metric-value">${f?esc(formatElev(f.altitude)):'—'}</div><div class="metric-small">Elipsoid, bukan MSL</div></div><div class="metric"><div class="metric-label">AKURASI H</div><div class="metric-value">${f?number(f.hAccuracy):'—'}</div><div class="metric-small">Estimasi radius</div></div><div class="metric"><div class="metric-label">AKURASI V</div><div class="metric-value">${f?number(f.vAccuracy):'—'}</div><div class="metric-small">Jika disediakan</div></div></div><div class="multi-info"><span class="pill neutral">${icon('clock')} ${f?fmtDate(f.fixTime):'Waktu belum ada'}</span><span class="pill neutral">${icon('signal')} ${f?esc(f.provider):'Penyedia belum ada'}</span><span class="pill ${isDemo?'orange':'neutral'}">${icon('info')} ${f?`${Math.max(0,Math.floor((Date.now()-f.fixTime)/1000))} dtk lalu`:'Menunggu'}</span></div><div class="gps-commands">${btn('get-gps',ui.gpsSearching?'Mencari Lokasi...':'Ambil Lokasi GPS','locate','btn-primary',ui.gpsSearching?'disabled':'')}${btn('demo-fix','Coba Mode Demo','compass','btn-outline')}</div>${isLow?`<div class="notice" style="margin-top:16px">${icon('warning')}<p><strong>Akurasi kurang baik.</strong> Nilai ${fmtNum(f.hAccuracy,1)} m melewati ambang ${fmtNum(db.settings.accuracyThreshold,0)} m. Disarankan ambil ulang; jika disimpan, diberi status kualitas rendah.</p></div>`:''}<div class="inline-info">${icon('info')}<span>Untuk GPS asli, buka melalui HTTPS atau localhost, izinkan lokasi presisi, dan aktifkan layanan lokasi perangkat. Elevasi dapat tidak tersedia atau kurang akurat.</span></div></div><div class="panel gps-panel"><div class="panel-head"><div><h2 class="panel-title">Catat Titik Survei</h2><p class="panel-subtitle">Tinjau fix lalu isi atribut titik</p></div>${icon('clipboard')}</div><form id="captureForm" class="form-stack"><label class="form-field"><span class="field-label">Proyek tujuan</span>${projectSelect(db.activeProjectId,'data-change="project"')}</label><div class="form-grid"><label class="form-field"><span class="field-label">Kode Titik</span><input class="field" name="code" required maxlength="35" value="${esc(nextPointCode())}" placeholder="TP-001" /></label><label class="form-field"><span class="field-label">Nama Titik</span><input class="field" name="name" required maxlength="100" placeholder="Contoh: Gerbang Utara" /></label><label class="form-field form-span"><span class="field-label">Catatan Lapangan (opsional)</span><textarea class="field" name="notes" maxlength="500" placeholder="Kondisi lokasi, patokan, atau keterangan tambahan..."></textarea></label></div>${isLow?'<label class="checkline"><input type="checkbox" name="allowLow"/><span>Saya memahami akurasi kurang baik dan ingin menyimpan dengan tanda kualitas rendah.</span></label>':''}${btn('capture-submit','Simpan Titik Survei','check','btn-primary btn-full',!has?'disabled':'') }<p class="caption">Penyimpanan aktif hanya setelah fix valid. Data GPS asli dan data simulasi diberi label sumber berbeda.</p></form></div></div>`;}
function renderData(){const points=pointList();return `${pageTitle('Data Survei','SURVEY DATA MANAGER',`${btn('navigate','Tambah Titik','plus','btn-primary','data-page="capture"')}`)}<div class="panel panel-pad"><div class="panel-head"><div><h2 class="panel-title">Arsip Titik Pengukuran</h2><p class="panel-subtitle">${points.length} dari ${db.points.length} titik tersimpan di browser ini</p></div>${badgeOnline()}</div><div class="list-controls"><div class="search-field">${icon('search')}<input class="field" id="pointSearch" value="${esc(ui.pointQuery)}" placeholder="Cari kode, nama, catatan, atau proyek" aria-label="Cari titik survei" /></div>${projectSelect(ui.dataProjectId,'data-change="dataProject"',true)}${btn('navigate','Ekspor','download','btn-outline','data-page="export"')}</div>${points.length?`<div class="data-table-wrap"><table class="data-table"><thead><tr><th>Nama / Kode</th><th>Koordinat</th><th>Elevasi</th><th>Akurasi H</th><th>Rekam</th><th>Status</th><th>Aksi</th></tr></thead><tbody>${points.map(p=>`<tr><td><button class="row-link" data-action="point-detail" data-id="${esc(p.id)}">${esc(p.code)} · ${esc(p.name)}</button><div class="caption">${esc(projectName(p.projectId))}</div></td><td class="mono">${coord(p.latitude)}<br/>${coord(p.longitude)}</td><td>${esc(formatElev(p.altitude))}</td><td>${p.hAccuracy===null?'—':displayLength(p.hAccuracy,1)}</td><td><span class="tiny">${fmtDate(p.recordedAt)}</span></td><td>${qualityBadge(p)}</td><td><div class="table-actions"><button class="mini-button" data-action="point-detail" data-id="${esc(p.id)}" aria-label="Detail titik">${icon('eye')}</button><button class="mini-button" data-action="edit-point" data-id="${esc(p.id)}" aria-label="Edit titik">${icon('edit')}</button><button class="mini-button" data-action="delete-point" data-id="${esc(p.id)}" aria-label="Hapus titik">${icon('trash')}</button></div></td></tr>`).join('')}</tbody></table></div>`:empty('database','Titik tidak ditemukan',db.points.length?'Coba ubah filter proyek atau kata kunci.':'Belum ada titik. Ambil GPS atau buat titik demonstrasi untuk mencoba fitur.',btn('navigate','Ambil Titik','crosshair','btn-primary','data-page="capture"'))}<p class="footer-note">Lokasi asli disimpan dengan presisi angka penuh, sedangkan tampilan dibulatkan untuk keterbacaan. Koordinat tidak dapat diedit manual melalui formulir metadata.</p></div>`;}
function renderHistory(){const hist=db.history.filter(h=>ui.historyProjectId==='all'||h.projectId===ui.historyProjectId);return `${pageTitle('Riwayat Aktivitas','AUDIT TRAIL',`${btn('navigate','Kelola Data','database','btn-outline','data-page="data"')}`)}<div class="panel panel-pad"><div class="panel-head"><div><h2 class="panel-title">Jejak Aktivitas Lokal</h2><p class="panel-subtitle">Penambahan, perubahan, dan penghapusan titik yang tercatat</p></div>${projectSelect(ui.historyProjectId,'data-change="historyProject"',true)}</div>${hist.length?`<div class="timeline">${hist.map(h=>`<div class="activity"><div class="activity-icon">${icon(h.action==='DELETE'?'trash':h.action==='EDIT'?'edit':h.action==='EXPORT'?'download':h.action==='PROJECT'?'folder':'check')}</div><div class="activity-body"><strong>${esc(h.message)}</strong><p>${esc(projectName(h.projectId))} · ${esc(h.action)}</p><div class="activity-date">${fmtDate(h.at)}</div></div>${h.pointId&&db.points.some(x=>x.id===h.pointId)?`<button class="text-action" data-action="point-detail" data-id="${esc(h.pointId)}">Detail ${icon('chevron')}</button>`:''}</div>`).join('')}</div>`:empty('clock','Belum ada aktivitas','Jejak perubahan tercatat saat menyimpan, mengedit, menghapus, dan mengekspor data.')}</div>`;}
function renderMap(){const pts=selectedPoints(ui.mapProjectId).sort((a,b)=>b.recordedAt-a.recordedAt);return `${pageTitle('Peta Survei','FIELD MAP EXPLORER',`${btn('navigate','Ambil Titik','plus','btn-primary','data-page="capture"')}`)}<div class="map-layout"><div class="panel map-card"><div class="map-toolbar"><div><strong>Peta Titik Survei</strong><div class="caption">${pts.length} titik · WGS84 (EPSG:4326)</div></div><div class="map-actions"><button class="map-control" data-action="map-zoom-in" title="Perbesar peta" aria-label="Perbesar peta">${icon('plus')}</button><button class="map-control" data-action="map-zoom-out" title="Perkecil peta" aria-label="Perkecil peta"><span style="font-size:20px">−</span></button><button class="map-control" data-action="map-fit" title="Tampilkan seluruh titik" aria-label="Tampilkan seluruh titik">${icon('target')}</button><button class="map-control" data-action="map-gps" title="Lokasi GPS yang terakhir dibaca" aria-label="Pusat ke GPS terakhir">${icon('locate')}</button></div></div><div id="mapViewport" class="map-viewport" role="application" aria-label="Peta dapat digeser dengan jari dan diperbesar menggunakan tombol"><div class="map-grid"></div><div class="map-tiles" id="mapTiles"></div><div id="mapMarkers"></div><div class="map-center-mark">${icon('crosshair')}</div><div class="map-banner">${navigator.onLine?'Lapisan peta memerlukan koneksi internet':'Mode offline — latar peta belum tersedia'}</div><div class="map-zoom-badge" id="mapZoomBadge">ZOOM ${ui.mapZoom}</div><div class="map-bottom-attribution">Data peta: <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">© OpenStreetMap contributors</a></div></div></div><div class="map-side"><div class="panel panel-pad"><div class="panel-head"><div><h2 class="panel-title">Titik di Peta</h2><p class="panel-subtitle">Ketuk titik untuk mengarahkan peta</p></div>${icon('layers')}</div><label class="form-field"><span class="field-label">Proyek yang ditampilkan</span>${projectSelect(ui.mapProjectId==='active'?db.activeProjectId:ui.mapProjectId,'data-change="mapProject"',true)}</label><div class="soft-hr"></div><div class="legend" style="margin-bottom:15px"><span><i class="legend-dot"></i>GPS Asli</span><span><i class="legend-dot demo"></i>Demo</span><span><i class="legend-dot current"></i>Lokasi fix</span></div><div class="map-side-list">${pts.length?pts.slice(0,60).map(p=>`<button class="map-side-point" data-action="map-focus" data-id="${esc(p.id)}"><span class="map-side-dot ${p.source==='DEMO'?'demo':''}"></span><span><strong>${esc(p.code)} · ${esc(p.name)}</strong><small>${coord(p.latitude)}, ${coord(p.longitude)}</small></span></button>`).join(''):empty('map','Peta masih kosong','Tambahkan titik survei untuk melihat marker di peta.')}</div></div><p class="footer-note">Peta dasar menggunakan tile OpenStreetMap saat online. Titik tersimpan dan grid tetap terlihat secara offline. Peta ini tidak menggantikan peta berskala atau hasil RTK.</p></div></div>`;}
function exportPoints(){const pid=ui.exportProjectId==='active'?db.activeProjectId:ui.exportProjectId;return db.points.filter(p=>(pid==='all'||p.projectId===pid)&&(!ui.dateFrom||new Date(p.recordedAt).toISOString().slice(0,10)>=ui.dateFrom)&&(!ui.dateTo||new Date(p.recordedAt).toISOString().slice(0,10)<=ui.dateTo)).sort((a,b)=>a.recordedAt-b.recordedAt);}
function renderExport(){const points=exportPoints(),f=ui.format,opts=[['csv','CSV','Spreadsheet / Excel','csv'],['geojson','GeoJSON','GIS / QGIS','geo'],['kml','KML','Google Earth','globe'],['pdf','PDF','Cetak / Simpan PDF','file']];return `${pageTitle('Ekspor Hasil Survei','DATA EXPORT',`${btn('navigate','Lihat Data','database','btn-outline','data-page="data"')}`)}<div class="export-layout"><div class="panel panel-pad"><div class="panel-head"><div><h2 class="panel-title">Konfigurasi Ekspor</h2><p class="panel-subtitle">Pilih proyek, tanggal, dan format output</p></div>${icon('download')}</div><div class="form-stack"><label class="form-field"><span class="field-label">Proyek yang diekspor</span><select class="select" data-change="exportProject"><option value="active" ${ui.exportProjectId==='active'?'selected':''}>Proyek aktif (${esc(currentProject().name)})</option><option value="all" ${ui.exportProjectId==='all'?'selected':''}>Semua proyek</option>${db.projects.map(p=>`<option value="${esc(p.id)}" ${ui.exportProjectId===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><div class="form-grid"><label class="form-field"><span class="field-label">Dari Tanggal</span><input class="field" type="date" value="${esc(ui.dateFrom)}" data-change="dateFrom"/></label><label class="form-field"><span class="field-label">Sampai Tanggal</span><input class="field" type="date" value="${esc(ui.dateTo)}" data-change="dateTo"/></label></div><div class="form-field"><span class="field-label">Format Dokumen</span><div class="format-options">${opts.map(([key,title,desc,ic])=>`<button type="button" class="format-card ${f===key?'selected':''}" data-action="select-format" data-format="${key}">${icon(ic)}<span><strong>${title}</strong><small>${desc}</small></span></button>`).join('')}</div></div><div class="pill green" style="justify-content:center">${icon('check')} ${points.length} titik siap diekspor</div>${btn('do-export',f==='pdf'?'Cetak / Simpan PDF':`Unduh ${f.toUpperCase()}`,'download','btn-primary btn-full',points.length?'':'disabled')}<p class="caption">Ekspor PDF membuka dialog cetak browser. Pilih “Simpan sebagai PDF”. CSV, GeoJSON dan KML diunduh sebagai berkas sungguhan.</p></div></div><div class="panel panel-pad"><div class="panel-head"><div><h2 class="panel-title">Pratinjau Data</h2><p class="panel-subtitle">Isi file berdasarkan filter dan format pilihan</p></div><span class="pill neutral">${f.toUpperCase()}</span></div>${points.length?`<div class="export-preview">${esc(exportPreview(points,f))}</div>`:empty('file','Tidak ada data untuk ekspor','Ubah filter atau simpan titik survei terlebih dahulu.')}<div class="soft-hr"></div><h3 class="panel-title">Cadangan Seluruh Data</h3><p class="caption">Cadangkan proyek, titik survei, pengaturan, dan riwayat dalam format JSON. Impor backup tersedia di Pengaturan.</p>${btn('backup-json','Unduh Backup JSON','archive','btn-outline btn-sm')}</div></div>`;}
function exportPreview(points,format){if(format==='csv')return toCsv(points).split('\n').slice(0,6).join('\n')+(points.length>5?'\n...':'');if(format==='geojson')return JSON.stringify(toGeoJSON(points),null,2).slice(0,1400)+'\n...';if(format==='kml')return toKml(points).slice(0,1400)+'\n...';return `LAPORAN SURVEI TOPOGRAFI\nProyek: ${ui.exportProjectId==='all'?'Semua proyek':ui.exportProjectId==='active'?currentProject().name:projectName(ui.exportProjectId)}\nJumlah titik: ${points.length}\nDibuat: ${fmtDate(Date.now())}\n\n${points.slice(0,8).map(p=>`${p.code} / ${p.name}\n${coord(p.latitude)}; ${coord(p.longitude)}; ${formatElev(p.altitude)}`).join('\n')}`;}
function renderSettings(){const s=db.settings;return `${pageTitle('Pengaturan Aplikasi','APP PREFERENCES',`${btn('manage-projects','Kelola Proyek','folder','btn-outline')}`)}<div class="settings-layout"><div class="panel panel-pad"><div class="panel-head"><div><h2 class="panel-title">Preferensi Pengukuran</h2><p class="panel-subtitle">Pengaturan tersimpan otomatis di perangkat</p></div>${icon('settings')}</div><div class="settings-item"><div><strong>Ambang Akurasi Horizontal</strong><span>Tandai lokasi dengan akurasi lebih buruk dari nilai ini.</span></div><select class="select" data-change="accuracyThreshold">${[5,10,15,20,50,100].map(n=>`<option value="${n}" ${Number(s.accuracyThreshold)===n?'selected':''}>${n} meter</option>`).join('')}</select></div><div class="settings-item"><div><strong>Satuan Panjang</strong><span>Untuk pembacaan ringkasan dan pengembangan lanjut.</span></div><select class="select" data-change="units"><option value="m" ${s.units==='m'?'selected':''}>Meter (m)</option><option value="ft" ${s.units==='ft'?'selected':''}>Kaki (ft)</option></select></div><div class="settings-item"><div><strong>Tema Antarmuka</strong><span>Warna tampilan dan kontras layar.</span></div><select class="select" data-change="theme"><option value="dark" ${s.theme==='dark'?'selected':''}>Gelap</option><option value="light" ${s.theme==='light'?'selected':''}>Terang</option></select></div><div class="settings-item"><div><strong>Peta Dasar</strong><span>Tile OpenStreetMap membutuhkan internet.</span></div><select class="select" data-change="basemap"><option value="osm" ${s.basemap==='osm'?'selected':''}>OpenStreetMap</option><option value="grid" ${s.basemap==='grid'?'selected':''}>Grid Offline</option></select></div><div class="settings-item"><div><strong>Izin Lokasi Android</strong><span>Browser akan meminta akses ketika tombol GPS digunakan.</span></div>${btn('check-permission','Periksa','locate','btn-outline btn-sm')}</div><div class="inline-info">${icon('info')}<span>Pembacaan elevasi browser (jika tersedia) bersumber dari layanan geolokasi. Satuan data mentah tetap meter dan derajat desimal meskipun preferensi tampilan diubah.</span></div></div><div class="dashboard-column"><div class="panel panel-pad"><div class="panel-head"><div><h2 class="panel-title">Penyimpanan & Backup</h2><p class="panel-subtitle">Tidak ada akun, server, atau sinkronisasi otomatis</p></div>${icon('lock')}</div><div class="form-stack"><div><strong style="font-size:12px">${db.projects.length} proyek · ${db.points.length} titik tersimpan</strong><div class="caption">Disimpan melalui localStorage browser di perangkat ini.</div></div>${btn('backup-json','Unduh Backup JSON','download','btn-outline btn-full')}<label class="btn btn-outline btn-full" style="cursor:pointer">${icon('upload')} Impor Backup JSON<input type="file" id="restoreInput" accept="application/json,.json" hidden /></label>${btn('manage-projects','Kelola Proyek','folder','btn-outline btn-full')}${btn('seed-demo','Isi Data Contoh untuk Demo','plus','btn-outline btn-full')}<div class="notice">${icon('warning')}<p>Data contoh selalu ditandai <strong>DEMO</strong>. Jangan gunakan sebagai hasil pengukuran lapangan atau laporan ilmiah.</p></div></div></div><div class="panel panel-pad"><div class="panel-head"><h2 class="panel-title">Tentang Prototipe</h2>${icon('info')}</div><p class="caption">TopoSurvey Mobile v1.0 — prototipe web/PWA Android. Pencatatan, peta, riwayat, dan ekspor terhubung. Belum merupakan aplikasi Kotlin/Room native dan belum diuji pada seluruh perangkat.</p><p class="caption"><strong>Privasi:</strong> GPS hanya diminta saat pengguna menekan tombol. Koordinat yang disimpan tidak dikirim ke backend. Jika menggunakan peta OpenStreetMap, permintaan tile terhubung ke penyedia peta.</p>${btn('show-help','Panduan & Batasan','info','btn-outline btn-sm')}</div></div></div>`;}
function showModal(title,subtitle,body,footer=''){const node=document.querySelector('#modal');node.innerHTML=`<div class="modal-box" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-header"><div><h2>${esc(title)}</h2><p>${esc(subtitle)}</p></div><button class="icon-button" data-action="close-modal" aria-label="Tutup">${icon('x')}</button></div>${body}${footer?`<div class="modal-actions">${footer}</div>`:''}</div>`;node.hidden=false;}
function closeModal(){document.querySelector('#modal').hidden=true;document.querySelector('#modal').innerHTML='';}
function showProjectForm(project=null){showModal(project?'Ubah Proyek':'Buat Proyek Baru','Data proyek disimpan secara lokal.',`<form id="projectForm" data-edit-id="${project?esc(project.id):''}" class="form-stack"><label><span class="field-label">Nama Proyek</span><input class="field" name="name" maxlength="80" required value="${esc(project?.name||'')}" placeholder="Contoh: Survei Area Kampus" autofocus /></label><label><span class="field-label">Deskripsi Proyek</span><textarea class="field" name="description" maxlength="300" placeholder="Tujuan survei dan area pengamatan">${esc(project?.description||'')}</textarea></label><button class="btn btn-primary btn-full" type="submit">${icon('check')} ${project?'Simpan Perubahan':'Buat Proyek'}</button></form>`);}
function showProjects(){showModal('Manajemen Proyek','Buat, pilih, ubah, dan hapus proyek survei.',`<div class="project-list">${db.projects.map(p=>`<div class="project-item ${p.id===db.activeProjectId?'active':''}"><div><strong>${esc(p.name)} ${p.id===db.activeProjectId?'<span class="pill green">AKTIF</span>':''}</strong><small>${db.points.filter(q=>q.projectId===p.id).length} titik · ${fmtDate(p.createdAt,{day:'numeric',month:'short',year:'numeric'})}</small></div><div class="project-actions"><button class="mini-button" data-action="activate-project" data-id="${esc(p.id)}" aria-label="Aktifkan">${icon('check')}</button><button class="mini-button" data-action="edit-project" data-id="${esc(p.id)}" aria-label="Ubah">${icon('edit')}</button><button class="mini-button" data-action="delete-project" data-id="${esc(p.id)}" aria-label="Hapus">${icon('trash')}</button></div></div>`).join('')}</div>`,btn('new-project','Proyek Baru','plus','btn-primary'));
}
function showPoint(p){ui.selectedPointId=p.id;const detail=[['Latitude',coord(p.latitude)],['Longitude',coord(p.longitude)],['Elevasi elipsoid',formatElev(p.altitude)],['Akurasi horizontal',p.hAccuracy===null?'Tidak tersedia':displayLength(p.hAccuracy,1)],['Akurasi vertikal',p.vAccuracy===null?'Tidak tersedia':displayLength(p.vAccuracy,1)],['Waktu fix',fmtDate(p.fixTime)],['Waktu simpan',fmtDate(p.recordedAt)],['Penyedia / sumber',p.provider],['Status kualitas',p.quality==='LOW_QUALITY'?'Akurasi rendah':'Diterima'],['Datum elevasi',p.altitude===null?'Tidak tersedia':'Elipsoid WGS84']];showModal(`${p.code} · ${p.name}`,`${projectName(p.projectId)} · ${p.source==='DEMO'?'DATA SIMULASI':'FIX PERANGKAT'}`,`<div class="detail-grid">${detail.map(([k,v])=>`<div class="detail-item"><small>${esc(k)}</small><strong>${esc(v)}</strong></div>`).join('')}</div><p class="caption"><strong>Catatan:</strong> ${esc(p.notes||'Tidak ada catatan.')}</p><p class="caption">Nilai ketinggian elipsoid tidak boleh langsung disamakan dengan elevasi di atas permukaan laut (MSL). ${p.source==='DEMO'?'Titik ini hanya untuk demonstrasi.':''}</p>`,`${btn('map-focus','Lihat di Peta','map','btn-outline',`data-id="${esc(p.id)}"`)}${btn('edit-point','Edit Metadata','edit','btn-primary',`data-id="${esc(p.id)}"`)}`);}
function showEditPoint(p){showModal('Ubah Metadata Titik','Koordinat hasil rekaman tidak bisa diedit di formulir ini.',`<form id="editPointForm" data-id="${esc(p.id)}" class="form-stack"><div class="form-grid"><label><span class="field-label">Kode Titik</span><input name="code" class="field" maxlength="35" value="${esc(p.code)}" required /></label><label><span class="field-label">Nama Titik</span><input name="name" class="field" maxlength="100" value="${esc(p.name)}" required /></label><label class="form-span"><span class="field-label">Catatan</span><textarea name="notes" class="field" maxlength="500">${esc(p.notes||'')}</textarea></label></div><div class="notice">${icon('lock')}<p>Latitude, longitude, elevasi, waktu fix, dan akurasi tetap menggunakan hasil pengukuran asli.</p></div><button class="btn btn-primary btn-full" type="submit">${icon('check')} Simpan Metadata</button></form>`);}
function showHelp(){showModal('Panduan Prototipe','Alur penggunaan TopoSurvey Mobile',`<div class="form-stack"><div class="caption"><strong>1. Buat atau pilih proyek.</strong> Proyek awal tersedia. Buat tambahan dari Beranda atau Pengaturan.<br/><br/><strong>2. Buka Ambil Koordinat.</strong> Tekan Ambil Lokasi GPS, aktifkan lokasi dan izinkan akses. Tunggu nilai latitude dan longitude.<br/><br/><strong>3. Periksa kualitas.</strong> GPS asli harus memiliki fix segar. Jika akurasi rendah, sistem meminta persetujuan eksplisit untuk menyimpan.<br/><br/><strong>4. Isi nama dan kode.</strong> Simpan ke arsip lokal. Titik otomatis tersedia di Data Survei, Peta, dan Riwayat.<br/><br/><strong>5. Ekspor.</strong> Pilih CSV, GeoJSON, KML, atau Cetak/Simpan PDF. Backup JSON dapat dipulihkan.<br/><br/><strong>6. Coba tanpa GPS.</strong> Gunakan Mode Demo untuk membuat fix simulasi, atau isi kumpulan data contoh dari Pengaturan. Data simulasi selalu ditandai DEMO.</div><div class="notice">${icon('info')}<p>Ini adalah prototipe PWA browser. GPS memerlukan HTTPS atau localhost, izin pengguna, serta perangkat yang mendukung geolocation. Akurasi GPS HP biasanya tidak memenuhi kebutuhan topografi berketelitian tinggi. Grid offline tidak sama dengan unduhan peta offline.</p></div></div>`,btn('close-modal','Mengerti','check','btn-primary'));}
function getBrowserFix(){if(!navigator.geolocation){ui.gpsError='Browser/perangkat tidak mendukung geolokasi.';render();notify(ui.gpsError,true);return;}if(!window.isSecureContext){ui.gpsError='GPS browser membutuhkan HTTPS atau localhost.';render();notify(ui.gpsError,true);return;}ui.gpsSearching=true;ui.gpsError='';ui.fix=null;render();navigator.geolocation.getCurrentPosition(pos=>{ui.gpsSearching=false;const c=pos.coords;const f={latitude:c.latitude,longitude:c.longitude,altitude:typeof c.altitude==='number'&&Number.isFinite(c.altitude)?c.altitude:null,hAccuracy:typeof c.accuracy==='number'&&Number.isFinite(c.accuracy)?c.accuracy:null,vAccuracy:typeof c.altitudeAccuracy==='number'&&Number.isFinite(c.altitudeAccuracy)?c.altitudeAccuracy:null,fixTime:pos.timestamp,provider:'Browser Geolocation API',source:'DEVICE'};if(!Number.isFinite(f.latitude)||!Number.isFinite(f.longitude)||f.latitude>90||f.latitude< -90||f.longitude>180||f.longitude< -180){ui.gpsError='Koordinat GPS di luar rentang valid.';ui.fix=null;}else if(Date.now()-f.fixTime>MAX_FIX_AGE_MS||f.fixTime>Date.now()+3000){ui.gpsError='Lokasi yang diterima sudah kedaluwarsa. Silakan ukur ulang.';ui.fix=null;}else {ui.fix=f;ui.mapCenter={lat:f.latitude,lon:f.longitude};notify('Lokasi GPS berhasil dibaca. Tinjau akurasi lalu simpan.');}render();},err=>{ui.gpsSearching=false;const msg=({1:'Izin lokasi ditolak. Aktifkan izin presisi pada pengaturan browser.',2:'Posisi tidak tersedia. Pastikan layanan lokasi aktif.',3:'Pencarian lokasi melewati batas waktu. Coba lagi di area terbuka.'})[err.code]||'Gagal membaca koordinat perangkat.';ui.gpsError=msg;render();notify(msg,true);},{enableHighAccuracy:true,maximumAge:0,timeout:20000});}
function demoFix(){const base={lat:-6.914744,lon:107.609810};ui.fix={latitude:base.lat,longitude:base.lon,altitude:768.5,hAccuracy:4.2,vAccuracy:7.5,fixTime:Date.now(),source:'DEMO',provider:'SIMULASI (bukan GPS asli)'};ui.gpsError='';ui.gpsSearching=false;ui.mapCenter={lat:base.lat,lon:base.lon};render();notify('Mode simulasi aktif. Data tidak berasal dari sensor GPS.');}
function savePointFromForm(){const form=document.querySelector('#captureForm');if(!form)return;if(!form.reportValidity())return;const f=ui.fix;if(!hasValidFix()){notify('Fix GPS belum valid atau sudah lebih dari 30 detik. Ambil lokasi baru.',true);render();return;}const code=safeText(form.elements.code.value,35),name=safeText(form.elements.name.value,100),notes=safeText(form.elements.notes.value,500);if(!code||!name){notify('Kode dan nama titik wajib diisi.',true);return;}if(db.points.some(p=>p.projectId===db.activeProjectId&&p.code.toLowerCase()===code.toLowerCase())){notify('Kode titik sudah digunakan pada proyek aktif.',true);return;}const low=qualityLow();if(low&&!form.elements.allowLow?.checked){notify('Akurasi rendah. Centang persetujuan atau ukur ulang.',true);return;}const point={id:id(),projectId:db.activeProjectId,code,name,notes,latitude:f.latitude,longitude:f.longitude,altitude:f.altitude,hAccuracy:f.hAccuracy,vAccuracy:f.vAccuracy,fixTime:f.fixTime,recordedAt:Date.now(),provider:f.provider,source:f.source,quality:low?'LOW_QUALITY':'ACCEPTED'};const ok=mutate(()=>{db.points.push(point);logEvent('CREATE',`Titik ${point.code} · ${point.name} disimpan${f.source==='DEMO'?' (data DEMO)':''}.`,point.id);});if(ok){ui.fix=null;ui.gpsError='';ui.page='data';ui.pointQuery='';render();notify(`Titik ${code} berhasil disimpan pada ${currentProject().name}.`);}}
function csvValue(value){const txt=value===null||value===undefined?'':String(value);return '"'+txt.replace(/"/g,'""')+'"';}
function toCsv(points){const columns=['project','code','name','latitude','longitude','altitude_ellipsoid_m','horizontal_accuracy_m','vertical_accuracy_m','fix_time_utc','recorded_at_utc','provider','source','quality','notes'];const rows=points.map(p=>[projectName(p.projectId),p.code,p.name,p.latitude,p.longitude,p.altitude,p.hAccuracy,p.vAccuracy,new Date(p.fixTime).toISOString(),new Date(p.recordedAt).toISOString(),p.provider,p.source,p.quality,p.notes]);return '\uFEFF'+[columns.map(csvValue).join(','),...rows.map(r=>r.map(csvValue).join(','))].join('\r\n')+'\r\n';}
function toGeoJSON(points){return {type:'FeatureCollection',name:'TopoSurvey',features:points.map(p=>({type:'Feature',id:p.id,geometry:{type:'Point',coordinates:p.altitude!==null?[p.longitude,p.latitude,p.altitude]:[p.longitude,p.latitude]},properties:{project:projectName(p.projectId),code:p.code,name:p.name,elevation_datum:p.altitude===null?null:'WGS84_ellipsoid',horizontal_accuracy_m:p.hAccuracy,vertical_accuracy_m:p.vAccuracy,fix_time_utc:new Date(p.fixTime).toISOString(),recorded_at_utc:new Date(p.recordedAt).toISOString(),source:p.source,quality:p.quality,notes:p.notes}}))};}
function xmlEsc(s){return String(s??'').replace(/[<>&"']/g,c=>({'<':'&lt;','>':'&gt;','&':'&amp;','"':'&quot;',"'":'&apos;'}[c]));}
function toKml(points){return '<?xml version="1.0" encoding="UTF-8"?>\n<kml xmlns="http://www.opengis.net/kml/2.2"><Document><name>TopoSurvey</name>\n'+points.map(p=>`<Placemark><name>${xmlEsc(p.code+' · '+p.name)}</name><description>${xmlEsc('Proyek: '+projectName(p.projectId)+' | Sumber: '+p.source+' | Elevasi: '+(p.altitude===null?'Tidak tersedia':p.altitude+' m WGS84 elipsoid')+' | Akurasi: '+p.hAccuracy+' m | '+(p.notes||''))}</description><Point><coordinates>${p.longitude},${p.latitude}${p.altitude!==null?','+p.altitude:''}</coordinates></Point></Placemark>`).join('\n')+'\n</Document></kml>';
}
function downloadFile(name,content,mime){const b=new Blob([content],{type:mime}),url=URL.createObjectURL(b),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),15000);}
function filename(ext){const date=new Date().toISOString().slice(0,10);return `TopoSurvey_${date}.${ext}`;}
function printReport(points){const pname=ui.exportProjectId==='all'?'Semua proyek':ui.exportProjectId==='active'?currentProject().name:projectName(ui.exportProjectId);document.querySelector('#printArea').innerHTML=`<div style="display:flex;align-items:start;justify-content:space-between"><div><h1>TOPO<span style="color:#088867">SURVEY</span></h1><strong>LAPORAN HASIL SURVEI TOPOGRAFI</strong></div><div style="text-align:right">${esc(fmtDate(Date.now()))}<br/>Dokumen hasil aplikasi</div></div><p class="print-meta">Proyek: <strong>${esc(pname)}</strong> · Jumlah titik: ${points.length}<br/>Datum horizontal: WGS84 (EPSG:4326) · Elevasi: WGS84 elipsoid jika tersedia</p><h2>Daftar Titik Pengukuran</h2><table><thead><tr><th>No</th><th>Kode</th><th>Nama</th><th>Latitude</th><th>Longitude</th><th>Elevasi h</th><th>Akurasi H</th><th>Sumber</th></tr></thead><tbody>${points.map((p,i)=>`<tr><td>${i+1}</td><td>${esc(p.code)}</td><td>${esc(p.name)}</td><td>${coord(p.latitude)}</td><td>${coord(p.longitude)}</td><td>${p.altitude===null?'—':fmtNum(p.altitude,2)}</td><td>${p.hAccuracy===null?'—':fmtNum(p.hAccuracy,1)}</td><td>${esc(p.source)}</td></tr>`).join('')}</tbody></table><div class="print-foot"><strong>Catatan:</strong> Perkiraan GPS perangkat bukan data geodesi presisi. Elevasi elipsoid tidak otomatis sama dengan elevasi MSL. Nilai bertanda DEMO merupakan data simulasi. Dibuat dengan TopoSurvey PWA Prototype.</div>`;window.print();}
function doExport(){const points=exportPoints();if(!points.length){notify('Tidak ada titik sesuai filter ekspor.',true);return;}const f=ui.format;const result={csv:()=>downloadFile(filename('csv'),toCsv(points),'text/csv;charset=utf-8'),geojson:()=>downloadFile(filename('geojson'),JSON.stringify(toGeoJSON(points),null,2),'application/geo+json;charset=utf-8'),kml:()=>downloadFile(filename('kml'),toKml(points),'application/vnd.google-earth.kml+xml;charset=utf-8'),pdf:()=>printReport(points)};if(!result[f])return;result[f]();mutate(()=>logEvent('EXPORT',`${points.length} titik diproses untuk ekspor ${f.toUpperCase()}${f==='pdf'?' (dialog cetak)':''}.`));notify(f==='pdf'?'Dialog cetak dibuka. Pilih Simpan sebagai PDF.':`${points.length} titik diekspor ke ${f.toUpperCase()}.`);}
function backupJSON(){downloadFile(filename('json'),JSON.stringify({...db,exportedAt:new Date().toISOString(),app:'TopoSurvey Prototype'},null,2),'application/json;charset=utf-8');notify('Backup JSON berhasil dibuat. Simpan berkas di lokasi aman.');}
function validateBackup(s){if(!s||!Array.isArray(s.projects)||!Array.isArray(s.points)||!Array.isArray(s.history)||!s.projects.length)throw Error('Struktur backup tidak sesuai.');if(s.projects.length>1000||s.points.length>20000||s.history.length>20000)throw Error('Berkas berisi terlalu banyak record.');const pids=new Set();for(const p of s.projects){if(typeof p.id!=='string'||!p.id||typeof p.name!=='string'||p.name.length>80||pids.has(p.id))throw Error('Data proyek tidak valid.');pids.add(p.id);}const ids=new Set();for(const p of s.points){if(typeof p.id!=='string'||ids.has(p.id)||!pids.has(p.projectId)||typeof p.code!=='string'||typeof p.name!=='string'||p.code.length>35||p.name.length>100||typeof p.latitude!=='number'||typeof p.longitude!=='number'||!Number.isFinite(p.latitude)||!Number.isFinite(p.longitude)||Math.abs(p.latitude)>90||Math.abs(p.longitude)>180||(p.altitude!==null&&p.altitude!==undefined&&!Number.isFinite(p.altitude))||!Number.isFinite(Number(p.recordedAt))||!Number.isFinite(Number(p.fixTime)))throw Error('Data titik tidak valid.');ids.add(p.id);}if(typeof s.activeProjectId!=='string'||!pids.has(s.activeProjectId))throw Error('Proyek aktif tidak ditemukan.');return {version:1,projects:s.projects,activeProjectId:s.activeProjectId,points:s.points.map(p=>({...p,altitude:p.altitude??null,hAccuracy:p.hAccuracy??null,vAccuracy:p.vAccuracy??null,notes:p.notes||'',source:p.source||'DEVICE',quality:p.quality||'ACCEPTED'})),history:s.history.filter(h=>h&&typeof h==='object'&&typeof h.message==='string'),settings:{accuracyThreshold:[5,10,15,20,50,100].includes(Number(s.settings?.accuracyThreshold))?Number(s.settings.accuracyThreshold):10,units:['m','ft'].includes(s.settings?.units)?s.settings.units:'m',theme:['light','dark'].includes(s.settings?.theme)?s.settings.theme:'dark',basemap:['osm','grid'].includes(s.settings?.basemap)?s.settings.basemap:'osm'}};}
async function restoreBackup(file){if(!file)return;if(file.size>10*1024*1024){notify('Berkas JSON terlalu besar (maksimal 10 MB).',true);return;}let parsed;try{parsed=validateBackup(JSON.parse(await file.text()));}catch(e){notify(`Impor ditolak: ${e.message}`,true);return;}if(!confirm(`Pulihkan ${parsed.projects.length} proyek dan ${parsed.points.length} titik? Seluruh data lokal saat ini akan DIGANTI. Unduh backup lama terlebih dahulu.`))return;const old=db;db=parsed;if(!persist()){db=old;return;}ui.pointQuery='';ui.dataProjectId='all';ui.mapProjectId='active';ui.exportProjectId='active';ui.fix=null;ui.page='dashboard';render();notify('Backup berhasil dipulihkan ke perangkat ini.');}
function seedData(){if(!confirm('Tambahkan 6 titik DATA DEMO ke proyek aktif? Ini bukan pengukuran GPS nyata.'))return;const center={lat:-6.914744,lon:107.609810};const samples=[['TP Demo Utara',-.0007,.0001,769.1],['TP Demo Timur',-.0003,.0011,767.9],['TP Demo Selatan',.0008,.0007,764.2],['TP Demo Barat',.0009,-.0009,766.5],['TP Demo Tengah',.0001,-.0001,null],['TP Demo Akses',-.0005,-.0013,770.0]];const now=Date.now();mutate(()=>{samples.forEach(([name,dLat,dLon,alt],i)=>{const p={id:id(),projectId:db.activeProjectId,code:nextPointCode(),name,notes:'Hanya demonstrasi prototipe, bukan data lapangan.',latitude:center.lat+dLat,longitude:center.lon+dLon,altitude:alt,hAccuracy:5.3,vAccuracy:8.7,fixTime:now-i*60000,recordedAt:now-i*60000,provider:'DATA DEMO',source:'DEMO',quality:'ACCEPTED'};db.points.push(p);logEvent('CREATE',`${p.code} · ${p.name} ditambahkan sebagai data DEMO.`,p.id);});});ui.mapCenter=center;ui.mapZoom=16;notify('Enam titik simulasi berhasil ditambahkan dan ditandai DATA DEMO.');}
function sanitizeCodeName(code,name,pid,excludeId=null){if(!code||!name)return 'Kode dan nama wajib diisi.';if(db.points.some(p=>p.id!==excludeId&&p.projectId===pid&&p.code.toLowerCase()===code.toLowerCase()))return 'Kode titik sudah dipakai pada proyek ini.';return null;}
function navigate(page){if(!PAGE_META[page])return;ui.page=page;closeModal();document.querySelector('#drawer').hidden=true;if(page==='map'&&!ui.mapBoundsInitialized){fitMap();ui.mapBoundsInitialized=true;}render();scrollTo({top:0,behavior:'instant'});}
function getPoint(id){return db.points.find(p=>p.id===id);}
function confirmDeletePoint(pid){const p=getPoint(pid);if(!p)return;if(!confirm(`Hapus titik ${p.code} · ${p.name}? Tindakan ini tidak dapat dibatalkan kecuali melalui backup.`))return;mutate(()=>{db.points=db.points.filter(q=>q.id!==pid);logEvent('DELETE',`Titik ${p.code} · ${p.name} dihapus dari proyek.`,pid,p.projectId);});closeModal();notify('Titik berhasil dihapus.');}
function confirmDeleteProject(pid){const p=db.projects.find(x=>x.id===pid);if(!p)return;if(db.projects.length===1){notify('Proyek terakhir tidak dapat dihapus.',true);return;}const count=db.points.filter(x=>x.projectId===pid).length;if(!confirm(`Hapus proyek ${p.name} beserta ${count} titiknya? Tindakan ini permanen. Cadangkan data sebelum menghapus.`))return;mutate(()=>{db.points=db.points.filter(x=>x.projectId!==pid);db.projects=db.projects.filter(x=>x.id!==pid);logEvent('PROJECT',`Proyek ${p.name} beserta ${count} titik dihapus.`,null,db.projects[0].id);if(db.activeProjectId===pid)db.activeProjectId=db.projects[0].id;});closeModal();notify('Proyek dihapus.');}
function d2r(v){return v*Math.PI/180;}
function haversine(a,b){const earth=6371008.8,lat=d2r(b.lat-a.lat),lon=d2r(b.lon-a.lon),v=Math.sin(lat/2)**2+Math.cos(d2r(a.lat))*Math.cos(d2r(b.lat))*Math.sin(lon/2)**2;return 2*earth*Math.atan2(Math.sqrt(v),Math.sqrt(1-v));}
function projectXY(lat,lon,z){const latRad=d2r(Math.max(-85.05112878,Math.min(85.05112878,lat))),world=256*Math.pow(2,z);return {x:(lon+180)/360*world,y:(1-Math.asinh(Math.tan(latRad))/Math.PI)/2*world};}
function inverseXY(x,y,z){const world=256*Math.pow(2,z),lon=x/world*360-180,lat=Math.atan(Math.sinh(Math.PI*(1-2*y/world)))*180/Math.PI;return {lat,lon:((lon+540)%360)-180};}
function fitMap(){const pts=selectedPoints(ui.mapProjectId);if(!pts.length){if(ui.fix)ui.mapCenter={lat:ui.fix.latitude,lon:ui.fix.longitude};return;}let lat=pts.reduce((s,p)=>s+p.latitude,0)/pts.length,lon=pts.reduce((s,p)=>s+p.longitude,0)/pts.length;ui.mapCenter={lat,lon};if(pts.length===1){ui.mapZoom=17;return;}const loLat=Math.min(...pts.map(p=>p.latitude)),hiLat=Math.max(...pts.map(p=>p.latitude)),loLon=Math.min(...pts.map(p=>p.longitude)),hiLon=Math.max(...pts.map(p=>p.longitude));for(let z=18;z>=3;z--){const a=projectXY(loLat,loLon,z),b=projectXY(hiLat,hiLon,z);if(Math.abs(b.x-a.x)<520&&Math.abs(b.y-a.y)<340){ui.mapZoom=z;break;}}}
function setMapFocus(point){ui.mapCenter={lat:point.latitude,lon:point.longitude};ui.mapZoom=Math.max(ui.mapZoom,16);ui.page='map';ui.mapBoundsInitialized=true;closeModal();render();}
let mapDrag=null;
function initMap(){const el=document.querySelector('#mapViewport');if(!el)return;drawMap();el.addEventListener('pointerdown',e=>{if(e.target.closest('button')||e.button!==0)return;mapDrag={id:e.pointerId,x:e.clientX,y:e.clientY,center:projectXY(ui.mapCenter.lat,ui.mapCenter.lon,ui.mapZoom),moved:false};el.setPointerCapture(e.pointerId);});el.addEventListener('pointermove',e=>{if(!mapDrag||e.pointerId!==mapDrag.id)return;const dx=e.clientX-mapDrag.x,dy=e.clientY-mapDrag.y;if(Math.abs(dx)+Math.abs(dy)>5)mapDrag.moved=true;const coord=inverseXY(mapDrag.center.x-dx,mapDrag.center.y-dy,ui.mapZoom);ui.mapCenter=coord;drawMap();});el.addEventListener('pointerup',()=>{mapDrag=null;});el.addEventListener('pointercancel',()=>{mapDrag=null;});el.addEventListener('wheel',e=>{e.preventDefault();ui.mapZoom=Math.max(3,Math.min(19,ui.mapZoom+(e.deltaY<0?1:-1)));drawMap();},{passive:false});}
function drawMap(){const el=document.querySelector('#mapViewport');if(!el)return;const tiles=document.querySelector('#mapTiles'),marks=document.querySelector('#mapMarkers');const w=el.clientWidth,h=el.clientHeight,z=ui.mapZoom,c=projectXY(ui.mapCenter.lat,ui.mapCenter.lon,z),n=Math.pow(2,z);if(navigator.onLine&&db.settings.basemap==='osm'){const minX=Math.floor((c.x-w/2)/256),maxX=Math.floor((c.x+w/2)/256),minY=Math.floor((c.y-h/2)/256),maxY=Math.floor((c.y+h/2)/256);const arr=[];for(let tx=minX;tx<=maxX;tx++)for(let ty=minY;ty<=maxY;ty++){if(ty<0||ty>=n)continue;const x=((tx%n)+n)%n;arr.push(`<img class="map-tile" draggable="false" alt="" loading="lazy" src="https://tile.openstreetmap.org/${z}/${x}/${ty}.png" style="left:${Math.round(tx*256-c.x+w/2)}px;top:${Math.round(ty*256-c.y+h/2)}px"/>`);}tiles.innerHTML=arr.join('');}else tiles.innerHTML='';const pts=selectedPoints(ui.mapProjectId),list=[...pts.map(p=>({id:p.id,lat:p.latitude,lon:p.longitude,demo:p.source==='DEMO'}))];if(ui.fix)list.push({id:'CURRENT',lat:ui.fix.latitude,lon:ui.fix.longitude,current:true,demo:ui.fix.source==='DEMO'});marks.innerHTML=list.map(p=>{const mp=projectXY(p.lat,p.lon,z),left=mp.x-c.x+w/2,top=mp.y-c.y+h/2;if(left< -50||left>w+50||top< -50||top>h+50)return '';return `<button class="map-marker ${p.current?'current':p.demo?'demo':''}" style="left:${left}px;top:${top}px" data-action="${p.current?'go-capture':'point-detail'}" ${p.current?'':`data-id="${esc(p.id)}"`} aria-label="${p.current?'Fix terakhir':'Lihat titik'}">${icon(p.current?'target':'pin')}</button>`;}).join('');document.querySelector('#mapZoomBadge').textContent=`ZOOM ${z} · ${coord(ui.mapCenter.lat)}, ${coord(ui.mapCenter.lon)}`;}
function handleAction(action,element){const pid=element.dataset.id;switch(action){case 'navigate':navigate(element.dataset.page);break;case 'open-drawer':{const drawer=document.querySelector('#drawer');drawer.hidden=false;drawer.innerHTML=`<div class="drawer-box"><div class="drawer-top"><strong>MENU TOPO<span style="color:var(--mint)">SURVEY</span></strong><button class="icon-button" data-action="close-drawer">${icon('x')}</button></div><nav class="desktop-nav">${Object.keys(PAGE_META).map(key=>`<button class="nav-link ${ui.page===key?'active':''}" data-action="navigate" data-page="${key}">${icon(PAGE_META[key][2])}${PAGE_META[key][0]}</button>`).join('')}</nav><p class="footer-note">Prototipe Survei Topografi Android v1.0</p></div>`;break;}case 'close-drawer':document.querySelector('#drawer').hidden=true;break;case 'close-modal':closeModal();break;case 'show-help':showHelp();break;case 'new-project':showProjectForm();break;case 'manage-projects':showProjects();break;case 'edit-project':showProjectForm(db.projects.find(p=>p.id===pid));break;case 'delete-project':confirmDeleteProject(pid);break;case 'activate-project':if(db.projects.some(p=>p.id===pid)){mutate(()=>{db.activeProjectId=pid;});ui.mapBoundsInitialized=false;closeModal();notify(`Proyek ${currentProject().name} diaktifkan.`);}break;case 'get-gps':getBrowserFix();break;case 'demo-fix':demoFix();break;case 'capture-submit':savePointFromForm();break;case 'point-detail':{const p=getPoint(pid);if(p)showPoint(p);break;}case 'edit-point':{const p=getPoint(pid);if(p)showEditPoint(p);break;}case 'delete-point':confirmDeletePoint(pid);break;case 'map-focus':{const p=getPoint(pid);if(p)setMapFocus(p);break;}case 'map-zoom-in':ui.mapZoom=Math.min(19,ui.mapZoom+1);drawMap();break;case 'map-zoom-out':ui.mapZoom=Math.max(3,ui.mapZoom-1);drawMap();break;case 'map-fit':fitMap();drawMap();break;case 'map-gps':if(ui.fix){ui.mapCenter={lat:ui.fix.latitude,lon:ui.fix.longitude};ui.mapZoom=17;drawMap();}else notify('Ambil koordinat GPS atau aktifkan simulasi terlebih dahulu.',true);break;case 'go-capture':navigate('capture');break;case 'select-format':ui.format=element.dataset.format;render();break;case 'do-export':doExport();break;case 'backup-json':backupJSON();break;case 'seed-demo':seedData();break;case 'check-permission':checkPermission();break;default:console.warn('Unknown action',action);}}
async function checkPermission(){if(!navigator.permissions){notify('Browser ini tidak menyediakan informasi status izin lokasi.');return;}try{const r=await navigator.permissions.query({name:'geolocation'});notify(`Status izin lokasi browser: ${r.state}.`);}catch{notify('Status izin lokasi tidak dapat dibaca; coba tombol Ambil Lokasi GPS.',true);}}
function handleChange(key,element){const v=element.value;switch(key){case 'project':if(db.projects.some(p=>p.id===v)){db.activeProjectId=v;persist();ui.mapBoundsInitialized=false;render();}break;case 'dataProject':ui.dataProjectId=v;render();break;case 'historyProject':ui.historyProjectId=v;render();break;case 'mapProject':ui.mapProjectId=v==='all'?'all':v;fitMap();render();break;case 'exportProject':ui.exportProjectId=v;render();break;case 'dateFrom':ui.dateFrom=v;render();break;case 'dateTo':ui.dateTo=v;render();break;case 'accuracyThreshold':db.settings.accuracyThreshold=Number(v);persist();render();notify('Ambang akurasi disimpan.');break;case 'units':db.settings.units=v;persist();render();notify('Preferensi satuan disimpan.');break;case 'theme':db.settings.theme=v;persist();render();break;case 'basemap':db.settings.basemap=v;persist();render();break;}}
function handleSubmit(form){if(form.id==='projectForm'){const editId=form.dataset.editId;const data=new FormData(form),name=safeText(data.get('name'),80),description=safeText(data.get('description'),300);if(!name){notify('Nama proyek wajib diisi.',true);return;}const ok=mutate(()=>{if(editId){const p=db.projects.find(p=>p.id===editId);if(p){p.name=name;p.description=description;logEvent('PROJECT',`Proyek ${name} diperbarui.`,null,p.id);}}else{const p={id:id(),name,description,createdAt:Date.now()};db.projects.push(p);db.activeProjectId=p.id;logEvent('PROJECT',`Proyek ${name} dibuat.`,null,p.id);}});if(ok){ui.mapBoundsInitialized=false;closeModal();notify('Proyek berhasil disimpan.');}return;}
if(form.id==='editPointForm'){const p=getPoint(form.dataset.id);if(!p)return;const data=new FormData(form),code=safeText(data.get('code'),35),name=safeText(data.get('name'),100),notes=safeText(data.get('notes'),500),error=sanitizeCodeName(code,name,p.projectId,p.id);if(error){notify(error,true);return;}const ok=mutate(()=>{p.code=code;p.name=name;p.notes=notes;logEvent('EDIT',`Metadata titik ${code} · ${name} diperbarui.`,p.id,p.projectId);});if(ok){closeModal();notify('Metadata titik berhasil diperbarui.');}return;}
if(form.id==='captureForm'){savePointFromForm();return;}}
function eventHandlers(){document.addEventListener('click',e=>{const node=e.target.closest('[data-action]');if(!node||node.disabled)return;e.preventDefault();handleAction(node.dataset.action,node);});document.addEventListener('change',e=>{const node=e.target;if(node.dataset.change)handleChange(node.dataset.change,node);if(node.id==='restoreInput'){restoreBackup(node.files?.[0]);node.value='';}});document.addEventListener('input',e=>{if(e.target.id==='pointSearch'){ui.pointQuery=e.target.value;const st=e.target.selectionStart;render();const input=document.querySelector('#pointSearch');if(input){input.focus();input.setSelectionRange(st,st);}}});document.addEventListener('submit',e=>{if(e.target.matches('#projectForm,#editPointForm,#captureForm')){e.preventDefault();handleSubmit(e.target);}});document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();document.querySelector('#drawer').hidden=true;}});document.querySelector('#modal').addEventListener('click',e=>{if(e.target===e.currentTarget)closeModal();});document.querySelector('#drawer').addEventListener('click',e=>{if(e.target===e.currentTarget)e.currentTarget.hidden=true;});window.addEventListener('online',()=>{renderNetwork();if(ui.page==='map')render();});window.addEventListener('offline',()=>{renderNetwork();if(ui.page==='map')render();});}
function registerSW(){if('serviceWorker' in navigator && (location.protocol==='https:'||location.hostname==='localhost'||location.hostname==='127.0.0.1')){navigator.serviceWorker.register('./sw.js').catch(err=>console.warn('Service worker cannot register',err));}}
eventHandlers();render();registerSW();
window.__TOPO_TEST__={getState:()=>JSON.parse(JSON.stringify(db)),getUI:()=>({...ui}),seedData,restore:validateBackup,toCsv,toGeoJSON,toKml,fmtDate,fitMap};
})();
